CREATE OR REPLACE FUNCTION get_restaurants_within_distance_v3(ref_point text, max_distance float, excluded_cuisines text[], required_cuisines text[], start_date_str text, end_date_str text, start_time_str text, end_time_str text) RETURNS TABLE (id text, name text, address text, rating float, price_level bigint, cuisine_type text[], business_status text, website text, latitude float, longitude float, distance float, available_slots json, area text, vegetarian_scale text) AS $$ DECLARE start_date date; end_date date; start_time time; end_time time; BEGIN start_date := CAST(NULLIF(start_date_str, '') AS date); end_date := CAST(NULLIF(end_date_str, '') AS date); start_time := COALESCE(CAST(start_time_str AS time), '00:00:00'::time); end_time := COALESCE(CAST(end_time_str AS time), '23:59:59'::time); RETURN QUERY WITH restaurant_distances AS (SELECT r.id, r.name, r.address, r.rating, r.price_level, r.cuisine_type, r.business_status, r.website, r.location, r.area, ST_Distance(r.location::geometry, ST_SetSRID(ST_GeomFromText(ref_point), 4326), true) as distance FROM restaurants r WHERE ST_DWithin(r.location::geometry, ST_SetSRID(ST_GeomFromText(ref_point), 4326), max_distance) AND NOT EXISTS (SELECT 1 FROM unnest(excluded_cuisines) ec WHERE EXISTS (SELECT 1 FROM unnest(r.cuisine_type) ct WHERE INITCAP(ct) = INITCAP(ec))) AND (required_cuisines IS NULL OR array_length(required_cuisines, 1) IS NULL OR EXISTS (SELECT 1 FROM unnest(required_cuisines) rc WHERE EXISTS (SELECT 1 FROM unnest(r.cuisine_type) ct WHERE INITCAP(ct) = INITCAP(rc))))), availability_slots AS (SELECT ra.id, json_agg(json_build_object('date', to_char(CAST(ra.date AS date), 'YYYY-MM-DD'), 'time_slot', to_char(CAST(ra.time_slot AS time), 'HH24:MI:SS'), 'uuid', ra.uuid)) as slots FROM restaurants_availability ra WHERE CAST(ra.date AS date) BETWEEN start_date AND end_date AND CAST(ra.time_slot AS time) BETWEEN start_time AND end_time GROUP BY ra.id) SELECT rd.id, rd.name, rd.address, rd.rating, rd.price_level, rd.cuisine_type, rd.business_status, rd.website, ST_Y(rd.location::geometry) as latitude, ST_X(rd.location::geometry) as longitude, rd.distance, COALESCE(a.slots, '[]'::json) as available_slots, rd.area, COALESCE(ds.vegetarian_scale, 'Unknown') as vegetarian_scale FROM restaurant_distances rd LEFT JOIN availability_slots a ON a.id = rd.id LEFT JOIN restaurants_dietary_stats ds ON ds.id = rd.id ORDER BY rd.distance; END; $$ LANGUAGE plpgsql;
